<?php
$runner=file_get_contents(__DIR__.'/../scripts/backend/cron_runner.sh');$docs=file_get_contents(__DIR__.'/../scripts/backend/cron_jobs.md');$passed=0;$failed=0;function cron_check(bool $v,string $n):void{global $passed,$failed;if($v){$passed++;echo "PASS: $n\n";}else{$failed++;echo "FAIL: $n\n";}}
cron_check(strpos($runner,'flock -n')!==false,'per-job lock is enforced');cron_check(strpos($runner,'--dry-run')!==false,'dry-run mode is supported');cron_check(strpos($runner,'CRON_TIMEOUT_SECONDS')!==false,'job timeout is configurable');cron_check(strpos($runner,'LOG_DIR')!==false,'job logs use a configurable directory');foreach(['game_tick','healthcheck','backup','reports','migrate'] as $job)cron_check(strpos($runner,$job)!==false,"{$job} job is registered");cron_check(strpos($docs,'Recommended crontab')!==false,'crontab installation is documented');cron_check(strpos($docs,'stale lock')!==false,'stale-lock recovery guidance is documented');if($failed){fwrite(STDERR,"$failed cron checks failed; $passed passed.\n");exit(1);}echo "All $passed cron checks passed.\n";
?>
